def divisorConnectivity(n, threshold, queries):
    parent = list(range(n + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for z in range(threshold + 1, n + 1):
        rz = find(z)
        for m in range(2 * z, n + 1, z):
            rm = find(m)
            if rm != rz:
                parent[rm] = rz
    return [1 if find(a) == find(b) else 0 for a, b in queries]
